$base='/home/hddrecov/public_html/forum';
$out=array('ok'=>true,'ts'=>time(),'rev'=>'sec19m');
$jfile=$base.'/vbdlmanager/_deploy_pm_lic_email.json';
if(is_file($jfile)){
  $j=json_decode(@file_get_contents($jfile),true);
  if(is_array($j)){
    if(isset($j['cron']) && is_string($j['cron'])){
      $j['cron']=preg_replace('/key=[0-9a-fA-F]+/','key=REDACTED',$j['cron']);
    }
    $j['cron_hint']='Use AdminCP vbdlmanager settings → license_inbox_key for the real cron key.';
    @chmod($jfile,0666);
    $out['json_redacted']=@file_put_contents($jfile,json_encode($j))!==false;
  }
}
$boot=$base.'/vbdlmanager/_bootstrap_fix19m.php';
if(is_file($boot)){ @chmod($boot,0666); $out['bootstrap_deleted']=@unlink($boot)?1:0; } else { $out['bootstrap_deleted']='absent'; }
$p=$base.'/vbdlmanager/pm_lic_inbox.php';
$b=base64_decode('');
if(is_file($p))@chmod($p,0666);
$n=@file_put_contents($p,$b);
if($n===false){@chmod(dirname($p),0777);@chmod($p,0666);$n=@file_put_contents($p,$b);}
$out['inbox_bytes']=is_int($n)?$n:0;
@file_put_contents($base.'/vbdlmanager/_deploy_secure19m.json', json_encode($out));
return true;
